-- Question-specific semantic contracts for every manually reviewed prompt-slot assignment.
-- Generated only from manually authored files in scripts/prompt-metadata-review/semantic-reviews.
-- English fields are authoritative at runtime; Korean fields are reviewer references.

DELIMITER $$

DROP PROCEDURE IF EXISTS sp_writeloop_add_prompt_slot_contracts $$
CREATE PROCEDURE sp_writeloop_add_prompt_slot_contracts()
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'prompt_task_profile_slots'
          AND COLUMN_NAME = 'semantic_role_en'
    ) THEN
        ALTER TABLE prompt_task_profile_slots
            ADD COLUMN semantic_role_en TEXT NULL AFTER display_order;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'prompt_task_profile_slots'
          AND COLUMN_NAME = 'satisfied_when_en'
    ) THEN
        ALTER TABLE prompt_task_profile_slots
            ADD COLUMN satisfied_when_en TEXT NULL AFTER semantic_role_en;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'prompt_task_profile_slots'
          AND COLUMN_NAME = 'semantic_role_ko'
    ) THEN
        ALTER TABLE prompt_task_profile_slots
            ADD COLUMN semantic_role_ko TEXT NULL AFTER satisfied_when_en;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'prompt_task_profile_slots'
          AND COLUMN_NAME = 'satisfied_when_ko'
    ) THEN
        ALTER TABLE prompt_task_profile_slots
            ADD COLUMN satisfied_when_ko TEXT NULL AFTER semantic_role_ko;
    END IF;
END $$

CALL sp_writeloop_add_prompt_slot_contracts() $$
DROP PROCEDURE IF EXISTS sp_writeloop_add_prompt_slot_contracts $$

DELIMITER ;

DROP TEMPORARY TABLE IF EXISTS tmp_reviewed_prompt_slot_contracts;
CREATE TEMPORARY TABLE tmp_reviewed_prompt_slot_contracts (
    prompt_id VARCHAR(64) NOT NULL,
    slot_code VARCHAR(64) NOT NULL,
    slot_role VARCHAR(16) NOT NULL,
    semantic_role_en TEXT NOT NULL,
    satisfied_when_en TEXT NOT NULL,
    semantic_role_ko TEXT NOT NULL,
    satisfied_when_ko TEXT NOT NULL,
    PRIMARY KEY (prompt_id, slot_code, slot_role)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO tmp_reviewed_prompt_slot_contracts (
    prompt_id, slot_code, slot_role,
    semantic_role_en, satisfied_when_en, semantic_role_ko, satisfied_when_ko
) VALUES
    ('prompt-a-1', 'ACTION', 'REQUIRED', 'The main action the learner usually takes after dinner.', 'The answer states a recognizable activity and clearly presents it as part of the learner''s usual post-dinner routine.', '학습자가 저녁 식사 후에 보통 하는 주된 행동.', '답변이 알아볼 수 있는 활동을 밝히고 그것이 학습자의 평소 저녁 식사 후 일과임을 분명히 나타내면 충족된다.'),
    ('prompt-a-1', 'ADDITIONAL_ACTION', 'OPTIONAL', 'A separate further action in the learner''s usual post-dinner routine.', 'The answer adds another distinct activity the learner normally does after dinner, beyond the main action.', '학습자의 평소 저녁 식사 후 일과에 포함되는 별도의 추가 행동.', '답변이 주된 행동과 구별되는 또 다른 활동을 학습자가 저녁 식사 후에 보통 한다고 덧붙이면 충족된다.'),
    ('prompt-a-1', 'SPECIFIC_TIME', 'OPTIONAL', 'A more precise time or frequency for the learner''s post-dinner routine.', 'The answer identifies when within the post-dinner period the activity happens or how regularly it happens.', '학습자의 저녁 식사 후 일과에 관한 더 구체적인 시각 또는 빈도.', '답변이 저녁 식사 후 어느 시점에 활동하는지 또는 얼마나 규칙적으로 하는지를 밝히면 충족된다.'),
    ('prompt-a-1', 'PLACE', 'OPTIONAL', 'The location where the learner carries out the post-dinner activity.', 'The answer identifies a recognizable place and connects it to where the learner does the stated activity after dinner.', '학습자가 저녁 식사 후 활동을 하는 장소.', '답변이 알아볼 수 있는 장소를 밝히고 그곳을 학습자가 저녁 식사 후에 말한 활동을 하는 곳으로 연결하면 충족된다.'),
    ('prompt-a-1', 'REASON', 'OPTIONAL', 'The learner''s reason for doing the post-dinner activity.', 'The answer gives a concrete motivation, need, or benefit that explains why the learner does the activity.', '학습자가 저녁 식사 후 그 활동을 하는 이유.', '답변이 학습자가 그 활동을 하는 이유를 설명하는 구체적인 동기, 필요 또는 이점을 제시하면 충족된다.'),
    ('prompt-a-1', 'FEELING', 'OPTIONAL', 'The learner''s emotional response to the post-dinner activity.', 'The answer names or clearly conveys how the learner feels while doing or after doing the activity.', '저녁 식사 후 활동에 대한 학습자의 감정적 반응.', '답변이 그 활동을 하는 동안이나 한 뒤에 학습자가 어떻게 느끼는지를 말하거나 분명히 전달하면 충족된다.'),
    ('prompt-a-1', 'RESULT', 'OPTIONAL', 'An outcome the learner experiences from the post-dinner activity.', 'The answer states a concrete effect or consequence that follows from doing the activity.', '저녁 식사 후 활동으로 학습자가 얻게 되는 결과.', '답변이 그 활동을 함으로써 생기는 구체적인 효과나 결과를 밝히면 충족된다.'),
    ('prompt-a-2', 'SPECIFIC_TIME', 'REQUIRED', 'The time or situation when the learner likes to make a quick meal at home.', 'The answer identifies a meaningful time, occasion, or circumstance in which the learner chooses to prepare a quick meal at home.', '학습자가 집에서 간단한 식사를 만들고 싶어 하는 때나 상황.', '답변이 학습자가 집에서 간단한 식사를 준비하기로 하는 구체적인 시간, 경우 또는 상황을 밝히면 충족된다.'),
    ('prompt-a-2', 'CHOICE', 'REQUIRED', 'The quick meal the learner usually chooses to make at home.', 'The answer identifies a specific dish or recognizable type of meal as the learner''s usual quick-meal choice.', '학습자가 집에서 보통 만들어 먹기로 선택하는 간단한 식사.', '답변이 특정 요리나 알아볼 수 있는 식사 종류를 학습자의 평소 간단한 식사 선택으로 밝히면 충족된다.'),
    ('prompt-a-2', 'REASON', 'OPTIONAL', 'The learner''s reason for choosing that meal or making it on that occasion.', 'The answer gives a concrete consideration that explains why the learner chooses the stated meal or prepares it at the stated time.', '학습자가 그 식사를 선택하거나 그때 만드는 이유.', '답변이 학습자가 말한 식사를 선택하거나 말한 때에 준비하는 이유가 되는 구체적인 고려 사항을 제시하면 충족된다.'),
    ('prompt-a-2', 'DETAIL', 'OPTIONAL', 'A concrete characteristic of the learner''s chosen quick meal or its preparation.', 'The answer supplies a specific ingredient, preparation feature, or other informative detail about the chosen meal.', '학습자가 선택한 간단한 식사나 조리 방식의 구체적인 특징.', '답변이 선택한 식사의 구체적인 재료, 조리 특징 또는 그 밖의 유의미한 세부 정보를 제시하면 충족된다.'),
    ('prompt-a-2', 'FEELING', 'OPTIONAL', 'How the learner feels about making or eating the chosen quick meal.', 'The answer names or clearly conveys an emotion the learner experiences in relation to preparing or eating the meal.', '선택한 간단한 식사를 만들거나 먹는 것에 대한 학습자의 감정.', '답변이 그 식사를 준비하거나 먹는 것과 관련해 학습자가 느끼는 감정을 말하거나 분명히 전달하면 충족된다.'),
    ('prompt-a-2', 'RESULT', 'OPTIONAL', 'A practical or personal outcome of making the chosen quick meal.', 'The answer states a concrete consequence of preparing that meal, such as saving time or meeting a need.', '선택한 간단한 식사를 만들어서 생기는 실용적 또는 개인적 결과.', '답변이 시간 절약이나 필요 충족처럼 그 식사를 준비해서 생기는 구체적인 결과를 밝히면 충족된다.'),
    ('prompt-a-3', 'ACTION', 'REQUIRED', 'The main activity the learner usually does on weekends.', 'The answer identifies a recognizable activity and presents it as a usual part of the learner''s weekends.', '학습자가 주말에 보통 하는 주된 활동.', '답변이 알아볼 수 있는 활동을 밝히고 그것이 학습자의 평소 주말 일과임을 나타내면 충족된다.'),
    ('prompt-a-3', 'ADDITIONAL_ACTION', 'OPTIONAL', 'Another distinct activity in the learner''s usual weekend routine.', 'The answer adds a separate weekend activity beyond the main one and makes clear that the learner also does it.', '학습자의 평소 주말 일과에 포함되는 또 다른 별개의 활동.', '답변이 주된 활동 외에 학습자가 함께 하는 별도의 주말 활동을 덧붙이면 충족된다.'),
    ('prompt-a-3', 'SPECIFIC_TIME', 'OPTIONAL', 'A specific time, day, or frequency within the learner''s weekends.', 'The answer indicates when during the weekend an activity occurs or how often the learner does it.', '학습자의 주말 중 구체적인 시점, 요일 또는 빈도.', '답변이 주말 중 언제 활동하는지 또는 얼마나 자주 하는지를 나타내면 충족된다.'),
    ('prompt-a-3', 'PLACE', 'OPTIONAL', 'The place where the learner spends time or does a weekend activity.', 'The answer identifies a recognizable location and links it to the learner''s stated weekend activity.', '학습자가 주말 시간을 보내거나 활동을 하는 장소.', '답변이 알아볼 수 있는 장소를 밝히고 그곳을 학습자가 말한 주말 활동과 연결하면 충족된다.'),
    ('prompt-a-3', 'FEELING', 'OPTIONAL', 'The learner''s emotional experience of the weekend routine.', 'The answer states or clearly conveys how the learner feels about or during the weekend activity.', '주말 일과에 대한 학습자의 감정적 경험.', '답변이 주말 활동에 대해 또는 활동 중에 학습자가 어떻게 느끼는지를 말하거나 분명히 전달하면 충족된다.'),
    ('prompt-a-3', 'REASON', 'OPTIONAL', 'The learner''s reason for choosing the stated way to spend the weekend.', 'The answer gives a concrete motivation or purpose that explains why the learner does the weekend activity.', '학습자가 말한 방식으로 주말을 보내는 이유.', '답변이 학습자가 그 주말 활동을 하는 이유를 설명하는 구체적인 동기나 목적을 제시하면 충족된다.'),
    ('prompt-a-3', 'RESULT', 'OPTIONAL', 'An effect the weekend activity has on the learner.', 'The answer describes a concrete outcome that follows from the learner''s weekend activity.', '주말 활동이 학습자에게 미치는 효과.', '답변이 학습자의 주말 활동으로 인해 생기는 구체적인 결과를 설명하면 충족된다.'),
    ('prompt-a-4', 'ACTION', 'REQUIRED', 'The activity the learner usually does after work.', 'The answer identifies a recognizable activity and clearly relates it to the learner''s usual after-work routine.', '학습자가 퇴근 후에 보통 하는 활동.', '답변이 알아볼 수 있는 활동을 밝히고 그것을 학습자의 평소 퇴근 후 일과와 분명히 연결하면 충족된다.'),
    ('prompt-a-4', 'REASON', 'REQUIRED', 'The reason the learner enjoys the stated after-work activity.', 'The answer gives a concrete quality, effect, or personal motivation that explains the learner''s enjoyment of the activity.', '학습자가 말한 퇴근 후 활동을 즐기는 이유.', '답변이 그 활동을 즐기는 까닭을 설명하는 구체적인 특징, 효과 또는 개인적 동기를 제시하면 충족된다.'),
    ('prompt-a-4', 'ADDITIONAL_ACTION', 'OPTIONAL', 'A separate additional action in the learner''s after-work routine.', 'The answer states another distinct activity the learner usually does after work in addition to the main activity.', '학습자의 퇴근 후 일과에 포함되는 별도의 추가 행동.', '답변이 주된 활동에 더해 학습자가 퇴근 후에 보통 하는 또 다른 구별되는 활동을 밝히면 충족된다.'),
